// Generated by `npm run media` (scripts/media.mjs). Do not edit by hand.
// Every name maps to the files in public/media/: stills as <name>-<width>.avif and .webp, loops as
// <name>-<width>.webm and .mp4 plus the poster still named in `poster`, textures (for the 3D scenes)
// as <name>-<width>.webp only. `aspect` is width : height.

export interface StillEntry {
  readonly kind: 'still'
  readonly aspect: readonly [number, number]
  readonly widths: readonly number[]
}

export interface TextureEntry {
  readonly kind: 'texture'
  readonly aspect: readonly [number, number]
  readonly widths: readonly number[]
}

export interface LoopEntry {
  readonly kind: 'loop'
  readonly aspect: readonly [number, number]
  readonly widths: readonly number[]
  readonly poster: string
}

export const MEDIA = {
  'street-dusk': { kind: 'still', aspect: [43, 24], widths: [640, 1280, 1920, 2560] },
  'rain-window': { kind: 'still', aspect: [43, 24], widths: [640, 1280, 1920, 2560] },
  'crema-macro': { kind: 'still', aspect: [43, 24], widths: [640, 1280, 1920, 2560] },
  'cup-still': { kind: 'still', aspect: [1, 1], widths: [640, 1280] },
  'surface-espresso': { kind: 'texture', aspect: [1, 1], widths: [1024, 512] },
  'surface-bloom': { kind: 'texture', aspect: [1, 1], widths: [1024, 512] },
  'surface-rosetta': { kind: 'texture', aspect: [1, 1], widths: [1024, 512] },
  'steam-loop-poster': { kind: 'still', aspect: [16, 9], widths: [640, 1280, 1920] },
  'steam-loop': { kind: 'loop', aspect: [16, 9], widths: [1920, 1280], poster: 'steam-loop-poster' },
} as const satisfies Record<string, StillEntry | LoopEntry | TextureEntry>

export type MediaName = keyof typeof MEDIA
export type StillName = {
  [K in MediaName]: (typeof MEDIA)[K] extends { kind: 'still' } ? K : never
}[MediaName]
export type LoopName = {
  [K in MediaName]: (typeof MEDIA)[K] extends { kind: 'loop' } ? K : never
}[MediaName]
export type TextureName = {
  [K in MediaName]: (typeof MEDIA)[K] extends { kind: 'texture' } ? K : never
}[MediaName]
